with feeders as (
    select
        md5(upper('HUB_DOCUMENT|' || (HUB_DOCUMENT_BK__CARD_NO))) as HUB_DOCUMENT_HK
        , CARD_STATUS as DOCUMENT_STATUS
        , CARD_EXPIRY as EXPIRY_DATE
        , CARD_TYPE as DOCUMENT_TYPE
        , cast(null as varchar) as STORAGE_REFERENCE
        , cast(null as varchar) as RECEIVED_DATE
        , cast(null as varchar) as DOCUMENT_CATEGORY
        , cast(null as varchar) as DOCUMENT_REFERENCE_NUMBER
        , cast(null as varchar) as DOCUMENT_NAME
        , cast(null as varchar) as ISSUE_DATE
        , 'BJAZ_CARD_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_card_dtls') }}
    where (nullif(trim(CARD_NO),'')) is not null
    union all
    select
        md5(upper('HUB_DOCUMENT|' || (HUB_DOCUMENT_BK__INWARD_ID))) as HUB_DOCUMENT_HK
        , cast(null as varchar) as DOCUMENT_STATUS
        , cast(null as varchar) as EXPIRY_DATE
        , cast(null as varchar) as DOCUMENT_TYPE
        , cast(null as varchar) as STORAGE_REFERENCE
        , DOC_REC_DATE as RECEIVED_DATE
        , PERTAIN_TO as DOCUMENT_CATEGORY
        , INWARD_NO as DOCUMENT_REFERENCE_NUMBER
        , cast(null as varchar) as DOCUMENT_NAME
        , cast(null as varchar) as ISSUE_DATE
        , 'BJAZ_HM_INWARD_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_inward_dtls') }}
    where (nullif(trim(INWARD_ID),'')) is not null
    union all
    select
        md5(upper('HUB_DOCUMENT|' || (HUB_DOCUMENT_BK__OMNI_INWARD_NO))) as HUB_DOCUMENT_HK
        , cast(null as varchar) as DOCUMENT_STATUS
        , cast(null as varchar) as EXPIRY_DATE
        , cast(null as varchar) as DOCUMENT_TYPE
        , cast(null as varchar) as STORAGE_REFERENCE
        , cast(null as varchar) as RECEIVED_DATE
        , cast(null as varchar) as DOCUMENT_CATEGORY
        , cast(null as varchar) as DOCUMENT_REFERENCE_NUMBER
        , COMPRESSED_FILE as DOCUMENT_NAME
        , cast(null as varchar) as ISSUE_DATE
        , 'BJAZ_REMEDINET_CLAIM_DETAILS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_remedinet_claim_details') }}
    where (nullif(trim(OMNI_INWARD_NO),'')) is not null
    union all
    select
        md5(upper('HUB_DOCUMENT|' || (HUB_DOCUMENT_BK__INWARD_NO))) as HUB_DOCUMENT_HK
        , cast(null as varchar) as DOCUMENT_STATUS
        , cast(null as varchar) as EXPIRY_DATE
        , cast(null as varchar) as DOCUMENT_TYPE
        , cast(null as varchar) as STORAGE_REFERENCE
        , cast(null as varchar) as RECEIVED_DATE
        , cast(null as varchar) as DOCUMENT_CATEGORY
        , INWARD_NO as DOCUMENT_REFERENCE_NUMBER
        , cast(null as varchar) as DOCUMENT_NAME
        , cast(null as varchar) as ISSUE_DATE
        , 'BJAZ_HAT_OCR_FINA_PERTICULARS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_ocr_fina_perticulars') }}
    where (nullif(trim(INWARD_NO),'')) is not null
    union all
    select
        md5(upper('HUB_DOCUMENT|' || (HUB_DOCUMENT_BK__OMNI_INWARD_NO_REPORT_ATTACH_PATH))) as HUB_DOCUMENT_HK
        , cast(null as varchar) as DOCUMENT_STATUS
        , cast(null as varchar) as EXPIRY_DATE
        , ATTACHMENT_TYPE as DOCUMENT_TYPE
        , cast(null as varchar) as STORAGE_REFERENCE
        , cast(null as varchar) as RECEIVED_DATE
        , cast(null as varchar) as DOCUMENT_CATEGORY
        , OMNI_INWARD_NO as DOCUMENT_REFERENCE_NUMBER
        , cast(null as varchar) as DOCUMENT_NAME
        , cast(null as varchar) as ISSUE_DATE
        , 'BJAZ_HM_PREAUTH_ATTACH' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_preauth_attach') }}
    where (coalesce(nullif('OMNI_INWARD:' || nullif(trim(OMNI_INWARD_NO),''), 'OMNI_INWARD:'), md5(normalise(upper(nullif(trim(REPORT_ATTACH_PATH),'')))))) is not null
    union all
    select
        md5(upper('HUB_DOCUMENT|' || (HUB_DOCUMENT_BK__INWARDNO))) as HUB_DOCUMENT_HK
        , cast(null as varchar) as DOCUMENT_STATUS
        , cast(null as varchar) as EXPIRY_DATE
        , cast(null as varchar) as DOCUMENT_TYPE
        , DOCINDEX as STORAGE_REFERENCE
        , CREATEDDATE as RECEIVED_DATE
        , cast(null as varchar) as DOCUMENT_CATEGORY
        , cast(null as varchar) as DOCUMENT_REFERENCE_NUMBER
        , IMAGENAME as DOCUMENT_NAME
        , FAXCREATEDDATE as ISSUE_DATE
        , 'NG_FAX_INWARD_DETAILS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ng_fax_inward_details') }}
    where (nullif('INWARD:' || nullif(trim(INWARDNO),''), 'INWARD:')) is not null
),

resolved as (
    select
        HUB_DOCUMENT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DOCUMENT_STATUS end) as DOCUMENT_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EXPIRY_DATE end) as EXPIRY_DATE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then DOCUMENT_TYPE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DOCUMENT_TYPE end)) as DOCUMENT_TYPE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then STORAGE_REFERENCE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then STORAGE_REFERENCE end)) as STORAGE_REFERENCE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RECEIVED_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then RECEIVED_DATE end)) as RECEIVED_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DOCUMENT_CATEGORY end) as DOCUMENT_CATEGORY,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then DOCUMENT_REFERENCE_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DOCUMENT_REFERENCE_NUMBER end)) as DOCUMENT_REFERENCE_NUMBER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DOCUMENT_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then DOCUMENT_NAME end)) as DOCUMENT_NAME,
        max(case when SOURCE_RUN = 'opus_health_delta3' then ISSUE_DATE end) as ISSUE_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_DOCUMENT_HK
),

hashed as (
    select
        *,
        case when DOCUMENT_STATUS is not null or EXPIRY_DATE is not null or DOCUMENT_TYPE is not null or STORAGE_REFERENCE is not null or RECEIVED_DATE is not null or DOCUMENT_CATEGORY is not null or DOCUMENT_REFERENCE_NUMBER is not null or DOCUMENT_NAME is not null or ISSUE_DATE is not null
                     then md5(upper(coalesce(cast(DOCUMENT_STATUS as varchar), '') || '|' || coalesce(cast(EXPIRY_DATE as varchar), '') || '|' || coalesce(cast(DOCUMENT_TYPE as varchar), '') || '|' || coalesce(cast(STORAGE_REFERENCE as varchar), '') || '|' || coalesce(cast(RECEIVED_DATE as varchar), '') || '|' || coalesce(cast(DOCUMENT_CATEGORY as varchar), '') || '|' || coalesce(cast(DOCUMENT_REFERENCE_NUMBER as varchar), '') || '|' || coalesce(cast(DOCUMENT_NAME as varchar), '') || '|' || coalesce(cast(ISSUE_DATE as varchar), '')))
                end as SAT_DOCUMENT_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_DOCUMENT_HK is not null
  and SAT_DOCUMENT_DEFINITION_HASHDIFF is not null
